;------------------------------------------------------------------------------
; $8169 - CHAR2LPT - Sends charecter in A to LPT
; Same as High Bank
; Called from 826E, 9307, 956D
; Arguments: A: ASCII charecter >=20, i.e. printable
; Outputs: REC = Success, A = 20 Low Battery
; RegMod: A
;------------------------------------------------------------------------------
CHAR2LPT:
	psh a                           ; 8169  fdc8         A is the ASCII charecter from input buffer?
	ldi a,0x7F                      ; 816B  b57f
	sta #(CE158_PRT_B_DIR)          ; 816D  fdaed00d     Bit 7 Read (BUSY), (ME1)
	lda #(CE158_PRT_A)              ; 8171  fda5d00e     Read CE-158 Port A,  (ME1)
	and #(CE158_PRT_A)              ; 8175  fda9d00e     Filter out input changes? (ME1)
	shl                             ; 8179  d9
	shl                             ; 817A  d9           Original    7 6 5 4 3 2 1 0
	shl                             ; 817B  d9           << 3        4 3 2 1 0 0 0 0
	pop a                           ; 817C  fd8a         Get our ASCII character from input buffer back
	bcs BRANCH_81B8                 ; 817E  8338         If #(PRT_A_IO) Bit 5, (Low Battery) skip to exit
	bii #(CE158_PRT_B),0x80         ; 8180  fdedd00f80   (ME1)
	bzs BRANCH_822C                 ; 8185  8ba5         If Bit 7 not set (I/F_BUSY) borrow another exit
	ani #(CE158_PRT_C),0x9F         ; 8187  fde9d0089f   Clear Bits 6,5 LPT_STROBE,LPT_DATA1 (ME1)
	eai a,0xFF                      ; 818C  bdff         A = A ^ FF. Invert due to inverters in LPT output
	shr                             ; 818E  d5           A = A >> 1. Shifted through Carry, 0 into MSB
	bcr BRANCH_8196                 ; 818F  8105         If Bit 0 set (inverted/shifted out), branch fwd
	ori #(CE158_PRT_C),0x20         ; 8191  fdebd00820   Set Bit 5, LPT_DATA1 (ME1)
BRANCH_8196:
	sta #(CE158_PRT_B)              ; 8196  fdaed00f     #(PRT_B_IO) = A (ME1). A = (A ^ FF) >> 1
	ldi a,0x80                      ; 819A  b580         Set up time delay
BRANCH_819C:
	dec a                           ; 819C  df           Carry set by first DEC, count 80->0
	bcs BRANCH_819C                 ; 819D  9303         If Carry set repeat, carry clear after hitting 0
	rie                             ; 819F  fdbe         Disable interrupts
	ori #(CE158_PRT_C),0x40         ; 81A1  fdebd00840   Set LPT_STROBE (ME1)
	ldi a,0x80                      ; 81A6  b580         Set up time delay
BRANCH_81A8:
	dec a                           ; 81A8  df           Carry set by first DEC, count 80->0
	bcs BRANCH_81A8                 ; 81A9  9303         If Carry set repeat, Carry clear after hitting 0
	ani #(CE158_PRT_C),0xBF         ; 81AB  fde9d008bf   CE-158 - Clear LPT_STROBE (ME1)
	sie                             ; 81B0  fd81         Enable Interrupts
	ldi a,0x80                      ; 81B2  b580         Set up time delay
BRANCH_81B4:
	dec a                           ; 81B4  df           Carry set by first DEC, count 80->0
	bcs BRANCH_81B4                 ; 81B5  9303         If Carry set repeat, Carry clear after hitting 0
	rtn                             ; 81B7  9a           Carry will be reset by last DEC above
BRANCH_81B8:
	ldi a,0x20                      ; 81B8  b520         Does A = 20 mean low battery?
	sec                             ; 81BA  fb           Carry used to indicate return state?
	rtn                             ; 81BB  9a           Set Carry Flag. SEC = Failure



;------------------------------------------------------------------------------
; $81BC - Sends charecter in A to RS232 Port
; Same as High Bank
; Called from 875B, 87EA, 90B1, 9EF0, 8247
; Arguments: A charecter to send
; Outputs: REC = Success, A = #(CE158_PRT_A) Bits 5-2  on failure
; RegMod: A
;------------------------------------------------------------------------------
CHAR2COM:
	sec                             ; 81BC  fb           Set Carry Flag
	psh u                           ; 81BD  fda8         Save U.
	sta ul                          ; 81BF  2a           A is character to send
	lda #(CE158_PRT_A)              ; 81C0  fda5d00e     #(CE158_PRT_A) is LPT/RS232 I/F Ctrl (ME1)
	and #(CE158_PRT_A)              ; 81C4  fda9d00e     Filter out changes (ME1)
	ani a,0x3C                      ; 81C8  b93c         Keep Bits 2->CTS, 3->CD, 4->DSR, 5->Low Battery
	bzr BRANCH_81E3                 ; 81CA  8917         Branch fwd if any bit 5-2 is set MODIFIED BRANCH ADDRESS
	lda (SETDEV_REG)                ; 81CC  a57857       (SETDEV_REG) = What device directed to RS232 B7=? B6=THRE B5? B4=CO B3=CI B2=PO B1=DO B0=KI
	ani a,0xC0                      ; 81CF  b9c0         Keep Bits 7-6 are set at power on
	shl                             ; 81D1  d9           A = A < 1. Bit 7 into Carry, 0 carried into LSB
	bcs BRANCH_81D6                 ; 81D2  8302         Branch fwd if Bit 7 was set.
	ldi a,0x04                      ; 81D4  b504         A = 6. Set bit 2
BRANCH_81D6:
	and #(CE158_UART_REGR)          ; 81D6  fda9d203     A = A & UART_STATUS. A=Bit6 of SETDEV_REG<<1 or $04 clear all but Bit7 (THRE) or Bit2 (PE)
	sec                             ; 81DA  fb           Set carry flag = failure
	bzs BRANCH_81E3                 ; 81DB  8b06         Branch fwd if Bit7 (THRE) or Bit2 (PE) not set
	lda ul                          ; 81DD  24           Our original A is in UL. Charecter to send.
	sta #(CE158_UART_DATAW)         ; 81DE  fdaed200     Writes A to UART (ME1)
	rec                             ; 81E2  f9           Reset Carry Flag = Success
BRANCH_81E3:
	pop u                           ; 81E3  fd2a         Get original U back, affectes Z only
	rtn                             ; 81E5  9a           A contains #(CE158_PRT_A) Bits 5-2 on failure



;------------------------------------------------------------------------------
; $81E6 - Manipulates LPT/UART registers
; Same as High Bank
; called from 8CBD, 99BC.  Alt entry at 822C, 8CBD
; Arguments: None
; Outputs: REC = Success, A = Failure type or UART data read
; RegMod: A
;------------------------------------------------------------------------------
RXCOM:
	lda #(CE158_PRT_A)              ; 81E6  fda5d00e     #(CE158_PRT_A) is LPT/RS232 I/F Ctrl (ME1)
	and #(CE158_PRT_A)              ; 81EA  fda9d00e     Filter out changes (ME1)
	ani a,0x3C                      ; 81EE  b93c         Keep Bits 2->CTS, 3->CD, 4->DSR, 5->Low Battery
	bzr BRANCH_8230                 ; 81F0  893e         Branch fwd if any bits 5-2 were set, failure exit
	lda #(CE158_UART_REGR)          ; 81F2  fda5d203     UART status register
	bii (SETDEV_REG),0x40           ; 81F6  ed785740     Test Bit6 B7=? B6=THRE B5? B4=CO B3=CI B2=PO B1=DO B0=KI
	bzs BRANCH_81FD                 ; 81FA  8b01         If THRE not set branch fwd (last byte not done)
	shl                             ; 81FC  d9           A = A << 1. UART Status register
BRANCH_81FD:
	bii a,0x02                      ; 81FD  bf02         Test Bit1 of A (Bit0 of CE158_UART_REGR) OE Overrun Error
	bzs BRANCH_822C                 ; 81FF  8b2b         If set we had an Rx overrun, branch to failure exit
	bii (SETDEV_REG),0x80           ; 8201  ed785780     Test Bit7 B7=? B6=THRE B5? B4=CO B3=CI B2=PO B1=DO B0=KI
	bzs BRANCH_8208                 ; 8205  8b01         Branch fwd if Bit7 not set
	shl                             ; 8207  d9           A = CE158_UART_REGR << 2
BRANCH_8208:
	bii a,0x70                      ; 8208  bf70         Keep bit 6-4, Bits 4-2 from original (CE158_UART_REGR)
	bzs BRANCH_8226                 ; 820A  8b1a         Bits 6-4 -> FE PE, if all bits clear branch (no error?)
	lda #(CE158_UART_DATAR)         ; 820C  fda5d202     Read UART Data Register to clear it
	bii (SETDEV_REG),0x20           ; 8210  ed785720     Test Bit5  ; B7=? B6=THRE B5? B4=CO B3=CI B2=PO B1=DO B0=KI
	bzs BRANCH_8222                 ; 8214  8b0c         Branch fwd if Bit5 not set, failure
	ldi a,0x15                      ; 8216  b515         sets: Bit4 WLS2, Bit2 SBS, Bit0 PI
	sta #(CE158_UART_REGW)          ; 8218  fdaed201     Writing UART control reg
	ldi a,0x05                      ; 821C  b505         sets: Bit2 SBS, Bit0 PI
	sta #(CE158_UART_REGW)          ; 821E  fdaed201     To pulse Bit 4?
BRANCH_8222:
	ldi a,0x40                      ; 8222  b540         Failure type
	sec                             ; 8224  fb           Set Carry Flag
