MAIN_ENTRY:
	rie                             ; 82EC  fdbe         Disable interrupts
	ani (OUTSTAT_REG),0xF7          ; 82EE  e97850f7     Clear Bit 3 = DCD (opposite of high bank)
	ldi uh,>ARW                     ; 82F2  687a         Point U to ARW
	ldi ul,<ARW                     ; 82F4  6a28         U = 7A28 = ARW
	ldi a,0xE1                      ; 82F6  b5e1         Intialize $7A28-$7A31 to:
	sin u                           ; 82F8  61
	ldi a,0xBA                      ; 82F9  b5ba         SPU, JMP $82F0
	sin u                           ; 82FB  61           This code segment sets PU to
	ldi a,>HB_JMP_FRM_LB            ; 82FC  b582         bank in upper half of
	sin u                           ; 82FE  61           the CE-158 ROM
	ldi a,<HB_JMP_FRM_LB            ; 82FF  b5f0
	sta (u)                         ; 8301  2e           Jumps to $7A28, runs code segment
BRANCH_8302:
	jmp ARW                         ; 8302  ba7a28       POKED in above, swtiches to HI bank.



