	vej 0xDE                        ; 83C7  de           Calc formula Y-reg points to, res to AR-X, Branch fwd 0D to 83D6 on error
	.db BRANCH_83D6-.-1             ; 83C8  0d           Forward branch to label
	vej 0xD0                        ; 83C9  d0           Convert AR-X to INT send to U, range of 8, branch fwd 0A to 83D6 on error
	.db 0x08                        ; 83CA  08           Low byte of address
	.db BRANCH_83D6-.-1             ; 83CB  0a           Forward branch to label
	lda ul                          ; 83CC  24
	bzs BRANCH_836A                 ; 83CD  9b65         If A=UL=0 branch back
	dec ul                          ; 83CF  62           If not zero DEC
	cpi ul,0x0F                     ; 83D0  6e0f
	ldi uh,0x13                     ; 83D2  6813
	bcs BRANCH_836A                 ; 83D4  936c         If UL >=0f Branch back
BRANCH_83D6:
	vej 0xE0                        ; 83D6  e0           Indicates if UH is not "00" error message
BRANCH_83D7:
	vej 0xE4                        ; 83D7  e4           Output error 1 and return to the editor



;------------------------------------------------------------------------------
; $83D8 - Branched to from 8307 via High Bank, ***JMP : Uses a calculated jump
; SPACE$ arg : (0-32d) Number of spaces
; ZONE arg   : (1-31d) Determine the block length of comma seperate data sent over COM with LPRINT
; Arguments  : XREG = Address, YREG = Token, AR-X is argument after command
; Outputs:
; RegMod:
;------------------------------------------------------------------------------
SPACE_STR__ZONE:
	vej 0xD0                        ; 83D8  d0           Convert AR-X to INT send to U, range of 8, branch fwd 83F8 on error
	.db 0x08                        ; 83D9  08           Low byte of address
	.db BRANCH_83F8-.-1             ; 83DA  1d           Forward branch to label
	cpi ul,0x21                     ; 83DB  6e21
	ldi uh,0x19                     ; 83DD  6819         U = 1921
	bcs BRANCH_83F8                 ; 83DF  8317         If UL >= 33d branch fwd, out of range
	ldi xl,<ARZ                     ; 83E1  4a08
	ldi xh,>ARZ                     ; 83E3  487a         X=7A08, ARZ
	lda ul                          ; 83E5  24           UL is command's argument
	bzs BRANCH_83F2                 ; 83E6  8b0a         If argument=0 branch fwd
	sta uh                          ; 83E8  28           UH = argument (1-31d)
	dec ul                          ; 83E9  62           UL = argument - 1 (0-30d)
	ldi a,0x20                      ; 83EA  b520         ASCII for space
BRANCH_83EC:
	sin x                           ; 83EC  41           (X) = A. Then X = X + 1. Copies A to (X) to (X + UL)
	lop ul,BRANCH_83EC              ; 83ED  8803         UL = UL - 1, loop back 'e' if Borrow Flag not set
	ldi xl,0x08                     ; 83EF  4a08         X = 7A08
	lda uh                          ; 83F1  a4           A = UH = argument
BRANCH_83F2:
	sjp XREG2STRBUF                 ; 83F2  bedfa1       X points to string to insert into String buffer. UL = #of chars
	.db BRANCH_83F8-.-1             ; 83F5  02           Jump if overflow
	ldi uh,0x00                     ; 83F6  6800
BRANCH_83F8:
	ldi xh,>B_TBL_8000_JMPS         ; 83F8  4880         Setting the destination address for 840A
	ldi xl,<B_TBL_8000_JMPS         ; 83FA  4a13         X=8013
BRANCH_83FC:
	ldi a,0x38                      ; 83FC  b538         Is this finding if this is OUTSTAT or CR/LF command?
	bii (OUTSTAT_REG),0x08          ; 83FE  ed785008     Keep Bit3, DCD
	bzs BRANCH_840A                 ; 8402  8b06         If Bit3 was not set
	ldi a,0xE1                      ; 8404  b5e1
	ori (CRLF_REG),0x08             ; 8406  eb785508     Set Bit3 in (CR/LF)
BRANCH_840A:
	sta (ARS)                       ; 840A  ae7a30       Store A, (38) NOP or (E1) SPU to ARS
	ldi a,0x24                      ; 840D  b524         SPU swtiches to High Bank of ROM
	sta (0x7A31)                    ; 840F  ae7a31       next opcode, UL is argument of command
	ldi a,0xFD                      ; 8412  b5fd         then: (24)      LDA UL
	sta (0x7A32)                    ; 8414  ae7a32       (FD 5E)   STX P ***JMP
	ldi a,0x5E                      ; 8417  b55e         Which saves X-Reg (8013) to PC (X set in 83F8)
	sta (0x7A33)                    ; 8419  ae7a33       i.e. this is destination address
	jmp ARS                         ; 841C  ba7a30       X = 8013 == B_TBL_8000_JMPS, low ROM is just (9A) RET
	.db 0xF8                        ; 841F  f8           High ROM has: (BA 79 FA 9A) JMP 79FA, RET



