CLD_CSV_LPR:
	vej 0xC0                        ; 901D  c0           Load next character/token to U-Reg
	ldi a,0x04                      ; 901E  b504         X = X + A + Carry
	adr x                           ; 9020  fdca         LLIST=901D+04=9021, LPRINT=9018+04=901C, LPRINT=9019+04=901D CSAVE=901A+04=901E,  CLOAD=901B+04=901F,  MERGE=901C+04=9020
