	lda xl                          ; 9026  04           XL is low byte of Command address
	psh a                           ; 9027  fdc8         Original LB of X-REG
	ldi ul,0x09                     ; 9029  6a09         Loop counter
	ldi uh,0x7A                     ; 902B  687a         U = 7A09 (ARZ + $01)
	ldi xl,0x6A                     ; 902D  4a6a         XH = HB of command, XL=6A



;------------------------------------------------------------------------------
; $902F - LLIST 906A=5E FD E0 C9 1B 68 28 FD 3C CD
; CLOAD CD 3C      FD 28   68 1B        C9 E0      FD 5E   4F 41 44
; 7A00  VMJ (3C) : LDX U : LDI UH,$1B : VZR (E0) : STX P :
; copied backwards 7A00-7A08, LPRINT 906A, **PRINT 906A, INPUT 8F6A**
;------------------------------------------------------------------------------
BRANCH_902F:
	lde x                           ; 902F  47           A = (X) then X = X - 1
	sta (u)                         ; 9030  2e
	lop ul,BRANCH_902F              ; 9031  8804         UL = UL - 1, loop back 'e' if Borrow Flag not set

; POKES in code from TABLE_906B
	pop a                           ; 9033  fd8a         A = original low byte of command before $902F
	sec                             ; 9035  fb           Set carry flag
	sbi a,0x1C                      ; 9036  b11c         LLIST  21-1C=05 C=1 -> LLIST  05<<3=28 C=0, MERGE  20-1C=## C=# -> MERGE  ##<<3=## C=#
	shl                             ; 9038  d9           LPRINT 1C-1C=00 C=1 -> LPRINT 00<<3=00 C=0, LPRINT 1D-1C=01 C=1 -> LPRINT 01<<3=08 C=0
	shl                             ; 9039  d9           CSAVE  1E-1C=## C=# -> CSAVE  ##<<3=#  C=#, CLOAD  1F-1C=## C=# -> CLOAD  ##<<3=# C=#
	shl                             ; 903A  d9           PRINT  10-1C=## C=# -> PRINT  ##<<3=#  C=#, PRINT  18-1C=## C=# -> PRINT  ##<<3=# C=#
	ldi xl,0x6B                     ; 903B  4a6b         INPUT  0A-1C=## C=# -> INPUT  ##<<3=#  C=#, INPUT  02-1C=## C=# -> INPUT  ##<<3=# C=#
	adr x                           ; 903D  fdca         LLIST 9093 C=0, LPRINT(1C) 906B C=0, LPRINT(1D) 9073 C=0
	lin x                           ; 903F  45           LLIST A=4 -> X=9094, A = (X) then INC X. Uses TABLE_906B
	and (SETDEV_REG)                ; 9040  a97857       Clear bits based on A. A = A & X KI = 01, DO = 02, PO = 04, CI = 08, CO = 10
	bzs BRANCH_904E                 ; 9043  8b09         1st byte in table does not match SETDEV mode
	sjp BRANCH_93CB                 ; 9045  be93cb       Compares C0 to (OPN_TBL)
	sta (0x7B9E)                    ; 9048  ae7b9e       A=C0, set in BRANCH_93CB, (79BE) in OUTPUT_BUFFER
	inc x                           ; 904B  44           skip three bytes in table if in SETDEV mode
	inc x                           ; 904C  44           use 1st three bytes if mode does not match
	inc x                           ; 904D  44           yse 2nd three bytes if mode does match
BRANCH_904E:
	lin x                           ; 904E  45           A = (X) then INC X
	sta uh                          ; 904F  28           Uses TABLE_906B
	lin x                           ; 9050  45           A = (X) then INC X
	sta ul                          ; 9051  2a           LLIST U=B754, CE-150 LLIST function
	lda (x)                         ; 9052  05           A = 58
	jmp ARX                         ; 9053  ba7a00       (9053) ***JMP to what was POKED in to ARX by $902F



