;------------------------------------------------------------------------------
; $9061 - Used by $902F
; Code copied reverse order to 7A09->00
;   Keyword What winds up in RAM
;   CLOAD:  CD 3C FD 28 68 1B C9 E0 FD 5E 4F 41 44
;   CSAVE:  CD 3C FD 28 68 1B C9 E0 FD 5E 41 56 45
;   MERGE:  CD 3C FD 28 68 1B C9 E0 FD 5E 52 47 45
;   PRINT:  CD 3C FD 28 68 1B C9 E0 FD 5E 49 4E 54
;   LPRINT: CD 3C FD 28 68 1B C9 E0 FD 5E 52 49 4E 54
;   LLIST:  CD 3C FD 28 68 1B C9 E0 FD 5E 49 53 54
; TABLE9061: (in RAM)
;------------------------------------------------------------------------------
TABLE_9061:
	.db 0xCD, 0x3C                  ; 9061  cd3c         7A09: vmj 0x3C  CD 3C  Checks whether token table exists
	.db 0xFD, 0x28                  ; 9063  fd28         7A0B: ldx u
	.db 0x68, 0x1B                  ; 9065  681b         7A0D: ldi uh,0x1B  68 1B  Error type to report
	.db 0xC9, 0xE0                  ; 9067  c9e0         7A0F: vzr 0xE0  C9 E0  Output error from UH, Return to editor
	.db 0xFD, 0x5E                  ; 9069  fd5e         7A11: stx p  FD 5E  Change program counter to what is in X



;------------------------------------------------------------------------------
; $906B - Used by 903F
; ?             CE-150   ?                           CE-158                    OPN EOL
;------------------------------------------------------------------------------
TABLE_906B:
	.db 0x04, 0xB2, 0xF4, 0x58, 0x93, 0xDE, 0xC0, 0x00; 906B               Byte 0 is SETDEV mode mask
	.db 0x04, 0xB2, 0xEC, 0x58, 0x93, 0xDE, 0xC0, 0x00; 9073               Byte 1 -> UH
	.db 0x10, 0xB8, 0xA6, 0x5C, 0x90, 0xBB, 0xC0, 0x00; 907B               Byte 2 -> UL
	.db 0x08, 0xB8, 0xF9, 0x5C, 0x90, 0xC3, 0xC0, 0x00; 9083               Byte 3 -> A   if SETDEV mode does not match mask
	.db 0x08, 0xB9, 0x95, 0x5C, 0x90, 0xBF, 0xC0, 0x00; 908B               Byte 4 -> UH
	.db 0x04, 0xB7, 0x54, 0x58, 0x93, 0x56, 0xC0, 0x00; 9093               Byte 5 -> UL
	.db 0x02, 0xE6, 0xB6, 0x60, 0x93, 0x6A, 0xC0, 0x00; 909B               Byte 6 -> A   if SETDEV mode does match mask
	.db 0x10, 0xE4, 0xF3, 0x5C, 0x94, 0xE0, 0xC0, 0x00; 90A3               Byte 7 -> 00 delimiter
	.db 0x08, 0xE4, 0xF3, 0x5C, 0x94, 0xE0, 0xC0, 0x00; 90AB
	.db 0x01, 0xC8, 0xFA, 0x60, 0x96, 0x60, 0xC0, 0x00; 90B3



